import * as React from 'react';
import * as BorderBeamPrimitive from '@exhuma/core';
import { cn } from '@/lib/utils';

export interface BorderBeamProps extends React.ComponentPropsWithoutRef<typeof BorderBeamPrimitive.BorderBeam> {
  className?: string;
}

export const BorderBeam = React.forwardRef<HTMLDivElement, BorderBeamProps>(
  ({ className, children, ...props }, ref) => (
    <BorderBeamPrimitive.BorderBeam
      ref={ref}
      className={cn(
        'pointer-events-none absolute inset-0 rounded-[inherit]',
        className
      )}
      {...props}
    >
      {children}
    </BorderBeamPrimitive.BorderBeam>
  )
);
BorderBeam.displayName = 'BorderBeam';

