import { Component, JSX, splitProps } from 'solid-js';
import * as BorderBeamPrimitive from '@exhuma/core';

export interface BorderBeamProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const BorderBeam: Component<BorderBeamProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <BorderBeamPrimitive.BorderBeam
      class={`pointer-events-none absolute inset-0 rounded-[inherit] ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </BorderBeamPrimitive.BorderBeam>
  );
};

