import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as BorderBeamPrimitive from '@exhuma/core';

export interface BorderBeamProps extends ViewProps {
  children?: React.ReactNode;
}

export function BorderBeam({ style, children, ...props }: BorderBeamProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

flutter.code:
import 'package:flutter/material.dart';
import 'package:exhuma/exhuma.dart' as exhuma;

class ExhumaBorderBeam extends StatelessWidget {
  final Widget child;

  const ExhumaBorderBeam({
    super.key,
    required this.child,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(16.0),
        border: Border.all(color: Theme.of(context).dividerColor),
        color: Theme.of(context).cardColor,
      ),
      padding: const EdgeInsets.all(20.0),
      child: child,
    );
  }
}
